import React, { Component } from "react";
import { observer, inject } from "mobx-react";

import ControlLabel from "react-bootstrap/lib/ControlLabel";
import FormGroup from "react-bootstrap/lib/FormGroup";
import FormControl from "react-bootstrap/lib/FormControl";
import HelpBlock from "react-bootstrap/lib/HelpBlock";

import isEmail from "validator/lib/isEmail";
import { OnboardPage } from "common/components";

@inject("registrationStore")
@observer
class EmailCard extends Component {
  constructor(...args) {
    super(...args);
    this.state = {
      email: "",
      formValid: false,
      loading: false,
      errorMessage: ""
    };
  }

  onNext = () => {
    this.setState({ loading: true });
    post("/api/v1/users", {
      body: { email: this.state.email },
      hideNotify: true
    })
      .then(response => {
        this.props.registrationStore.setCookie(
          response.data.id,
          this.state.email
        );
        return post("/api/v1/users/send-confirmation-code", {
          body: { id: response.data.id }
        }).then(() => {
          this.props.history.push("/signup/confirmation-code");
          this.setState({ loading: false });
        });
      })
      .catch(err => {
        this.setState({
          loading: false,
          errorMessage: err.data ? err.data.message : err.message
        });
      });
  };

  onChange = evt => {
    this.setState({
      email: evt.target.value,
      formValid: isEmail(evt.target.value)
    });
  };

  render() {
    const { errorMessage } = this.state;
    return (
      <div>
        <OnboardPage
          title="Create a new carespace"
          description={
            <span>
              Enter your email address to start creating your carespace on
              Stitch.
            </span>
          }
          onNext={this.onNext}
          loading={this.state.loading}
          disableNext={!this.state.formValid}
        >
          <FormGroup
            bsSize="large"
            validationState={(errorMessage && "error") || null}
          >
            <ControlLabel>Email Address</ControlLabel>
            <FormControl
              name={`email_${new Date().getTime()}`}
              required
              autoFocus
              autoComplete="off"
              type="email"
              placeholder="Email address"
              value={this.state.email}
              onChange={this.onChange}
            />
            {errorMessage && (
              <HelpBlock className="text-left">
                <i className="fa fa-exclamation-circle" />
                {errorMessage}
              </HelpBlock>
            )}
          </FormGroup>
        </OnboardPage>
      </div>
    );
  }
}

export default EmailCard;



