import React, { Component } from "react";
import { inject, observer } from "mobx-react";
import slugify from "slugify";
import { withRouter } from "react-router-dom";

import MenuItem from "react-bootstrap/lib/MenuItem";
import Modal from "react-bootstrap/lib/Modal";
import Form from "react-bootstrap/lib/Form";
import Col from "react-bootstrap/lib/Col";
import FormGroup from "react-bootstrap/lib/FormGroup";
import ControlLabel from "react-bootstrap/lib/ControlLabel";
import FormControl from "react-bootstrap/lib/FormControl";
import HelpBlock from "react-bootstrap/lib/HelpBlock";
import Button from "react-bootstrap/lib/Button";

@inject("groupStore", "sidemenuStore")
@observer
class NavItemRename extends Component {
  constructor(...args) {
    super(...args);
    this.state = {
      showModal: false,
      groupName: "",
      groupSlug: ""
    };
  }

  openModal = () => {
    this.setState({
      showModal: true,
      groupName: this.props.groupStore.groupName,
      groupSlug: `#${this.props.groupStore.group.slug}`
    });
  };

  closeModal = () => {
    this.setState({ showModal: false });
  };

  cleanName = e => {
    const re = /^[\w\-\s]+$/;
    if (!re.test(e.key)) {
      e.preventDefault();
    }
  };

  canRenameRoom = () => {
    const { groupName } = this.state;
    return groupName.trim() !== "";
  };

  handleChangeName = event => {
    const value = event.target.value;

    this.setState({
      groupName: value,
      groupSlug: `#${slugify(value, { lower: true })}`
    });
  };

  handleSubmit = () => {
    this.props.groupStore.rename(this.state.groupName.trim());
    this.setState({ showModal: false });
  };

  render() {
    return [
      <MenuItem key="rename_menuitem" onClick={this.openModal}>
        Rename Room
      </MenuItem>,
      <Modal
        key="rename_modal"
        show={this.state.showModal}
        onHide={this.closeModal}
      >
        <Modal.Header>
          <Modal.Title>Rename Room</Modal.Title>
          <a role="link" onClick={this.closeModal}>
            <i className="fa fa-close" />
          </a>
        </Modal.Header>

        <Modal.Body>
          <Form horizontal>
            <FormGroup bsSize="large">
              <Col componentClass={ControlLabel} sm={3}>
                Name
              </Col>

              <Col sm={9}>
                <FormControl
                  name="groupName"
                  type="text"
                  autoFocus
                  maxLength="25"
                  placeholder="e.g. Radiology"
                  value={this.state.groupName}
                  onKeyPress={this.cleanName}
                  onChange={this.handleChangeName}
                />
                <HelpBlock className="text-muted m-b-0">
                  Names must be shorter than 25 characters and without
                  punctuation.
                </HelpBlock>
              </Col>
            </FormGroup>
            <FormGroup bsSize="large">
              <Col componentClass={ControlLabel} sm={3} className="optional">
                Reference
                <br />
                <span>(automatic)</span>
              </Col>

              <Col sm={9}>
                <FormControl
                  name="reference"
                  placeholder="e.g. #radiology"
                  value={this.state.groupSlug}
                  disabled
                />
                <HelpBlock className="text-muted m-b-0">
                  The reference name is the unique ID for a room and can be
                  mentioned in a conversation to link right to it.
                </HelpBlock>
              </Col>
            </FormGroup>
          </Form>
        </Modal.Body>

        <Modal.Footer>
          <Button bsSize="large" onClick={this.closeModal}>
            Cancel
          </Button>
          <Button
            bsSize="large"
            bsStyle="primary"
            disabled={!this.canRenameRoom()}
            onClick={this.handleSubmit}
          >
            Rename
          </Button>
        </Modal.Footer>
      </Modal>
    ];
  }
}

export default withRouter(NavItemRename);



